import json
from pathlib import Path
items=[
(2,'Merge Sort','Return a sorted copy of an integer array. Do not mutate the input. Preserve duplicate values. Use a shared auxiliary array, not a new array at every recursive call.','static int[] solve(int[] input)', 'return new int[0];', 'new int[][]{{},{7},{3,1,3,-2},{9,8,7,6}}','String.valueOf(Arrays.equals(got, expected))','int[] expected=input.clone(); Arrays.sort(expected); int[] got=solve(input.clone());','int[] input', ['Empty array → []','[7] → [7]','[3,1,3,−2] → [−2,1,3,3]','[9,8,7,6] → [6,7,8,9]'], ['Half-open ranges and a terminating base case','Stable merge chooses left on equality','Θ(n log n) time and Θ(n) auxiliary storage']),
(6,'Disjoint Set Union','Process unions on n initially isolated vertices and return the component count. Use path compression and union by size or rank. Duplicate unions must not reduce the count.','static int solve(int n, int[][] edges)','return n;',None,None,None,None,['n=4, edges=[] → 4','n=4, [(0,1),(1,2),(0,2)] → 2','n=3, [(0,0),(1,2)] → 2'],['find returns a representative','Only successful union decreases count','Near-constant amortized operations']),
(6,'Prim’s Algorithm','Return the MST total weight for an undirected graph with vertices 0..n−1. Edge rows are [u,v,weight]. Return 0 for n=0. Throw IllegalArgumentException if disconnected. Accumulate weights in long.','static long solve(int n, int[][] edges)','return 0L;',None,None,None,None,['n=4, [(0,1,2),(0,2,3),(1,2,1),(1,3,4),(2,3,5)] → 7','n=1, [] → 0','n=2, [(0,1,−3)] → −3','n=3, [(0,1,1)] → IllegalArgumentException'],['Heap contains crossing candidates','Skip stale entries for visited vertices','Count visited vertices to detect disconnection']),
(7,'Kosaraju’s Algorithm','Return the number of strongly connected components in a directed graph, including isolated vertices. Edge rows are [from,to]. Use finish order and the transpose.','static int solve(int n, int[][] edges)','return n;',None,None,None,None,['n=4, [(0,1),(1,2),(2,0),(2,3)] → 2','n=3, [] → 3','n=2, [(0,1),(1,0)] → 1'],['First pass records vertices on exit','Second pass uses the transpose in decreasing finish order','O(V+E); recursion depth considered']),
(8,'Edit Distance','Return the minimum number of unit-cost insertions, deletions, and substitutions converting a into b. Inputs are non-null Java strings. Empty strings are valid.','static int solve(String a, String b)','return 0;',None,None,None,None,['cat, cut → 1','empty, abc → 3','kitten, sitting → 3','same, same → 0'],['State is a pair of prefix lengths','Initialize both empty-prefix boundaries','Transition takes min of delete, insert, substitute']),
(9,'KMP Preprocessing','Return the prefix-function array. pi[i] is the longest proper prefix of s[0..i] that is also a suffix. Empty input returns an empty array.','static int[] solve(String s)','return new int[0];',None,None,None,None,['ababaca → [0,0,1,2,3,0,1]','aaaa → [0,1,2,3]','abc → [0,0,0]','empty → []'],['Fallback uses pi[j−1], not j−1','Proper border cannot equal full prefix length','O(n) amortized character comparisons']),
(9,'Polynomial Rolling Hash','Return the high-order polynomial hash of s with a=1,…,z=26, base 31, modulus 1,000,000,007. Inputs contain only lowercase ASCII letters, including empty. Use long multiplication.','static long solve(String s)','return 0L;',None,None,None,None,['empty → 0','a → 1','ab → 33','abc → 1026'],['h=(h*31+symbol)%MOD','Document the orientation of powers','Equal hashes do not prove equal strings']),
(10,'Kasai’s Algorithm','Given a string and a valid suffix array permutation, return LCP with LCP[0]=0, LCP[r]=lcp(SA[r],SA[r−1]). Use inverse ranks and carry the match length.','static int[] solve(String s, int[] sa)','return new int[0];',None,None,None,None,['banana, [5,3,1,0,4,2] → [0,1,3,0,0,2]','aaa, [2,1,0] → [0,1,2]','a, [0] → [0]','empty, [] → []'],['Build inverse rank array','Reset carried length at rank 0','Decrease carried length by at most one each text step'])]
tasks=[]
for i,x in enumerate(items):
 l,title,brief,sig,body,*rest=x
 tasks.append(dict(id=i,lesson=l,title=title,brief=brief,signature=sig,starter=sig+' {\n  // TODO: implement without looking at the reference.\n  '+body+'\n}',tests=x[-2],rubric=x[-1]))
Path('tasks.json').write_text(json.dumps(tasks,indent=2,ensure_ascii=False))
# Downloadable standalone test files: learner replaces solve, runs java Practice.java.
cases=[
'''for(int[] a:new int[][]{{},{7},{3,1,3,-2},{9,8,7,6}}){ int[] copy=a.clone(),expected=a.clone();Arrays.sort(expected);check(Arrays.equals(solve(a),expected));check(Arrays.equals(a,copy)); }''',
'''check(solve(4,new int[][]{})==4);check(solve(4,new int[][]{{0,1},{1,2},{0,2}})==2);check(solve(3,new int[][]{{0,0},{1,2}})==2);''',
'''check(solve(4,new int[][]{{0,1,2},{0,2,3},{1,2,1},{1,3,4},{2,3,5}})==7);check(solve(1,new int[][]{})==0);check(solve(2,new int[][]{{0,1,-3}})==-3);boolean threw=false;try{solve(3,new int[][]{{0,1,1}});}catch(IllegalArgumentException e){threw=true;}check(threw);''',
'''check(solve(4,new int[][]{{0,1},{1,2},{2,0},{2,3}})==2);check(solve(3,new int[][]{})==3);check(solve(2,new int[][]{{0,1},{1,0}})==1);''',
'''check(solve("cat","cut")==1);check(solve("","abc")==3);check(solve("kitten","sitting")==3);check(solve("same","same")==0);''',
'''check(Arrays.equals(solve("ababaca"),new int[]{0,0,1,2,3,0,1}));check(Arrays.equals(solve("aaaa"),new int[]{0,1,2,3}));check(Arrays.equals(solve("abc"),new int[]{0,0,0}));check(solve("").length==0);''',
'''check(solve("")==0);check(solve("a")==1);check(solve("ab")==33);check(solve("abc")==1026);''',
'''check(Arrays.equals(solve("banana",new int[]{5,3,1,0,4,2}),new int[]{0,1,3,0,0,2}));check(Arrays.equals(solve("aaa",new int[]{2,1,0}),new int[]{0,1,2}));check(Arrays.equals(solve("a",new int[]{0}),new int[]{0}));check(solve("",new int[]{}).length==0);''']
Path('assets/practice').mkdir(exist_ok=True)
for t,c in zip(tasks,cases):
 Path(f'assets/practice/Practice{t["id"]}.java').write_text('import java.util.*;\nclass Practice'+str(t['id'])+' {\n'+t['starter']+'\npublic static void main(String[] args) {\n'+c+'\nSystem.out.println("All listed checks passed");\n}\nstatic void check(boolean ok){if(!ok)throw new AssertionError("A listed check failed");}\n}\n')
